"""Generate same-operation Matrix adapters for lossless coefficient values."""

import argparse
import json
from pathlib import Path

from generate_matrix_bindings import S, snake

ROOT = Path(__file__).resolve().parent.parent
OPS = [entry for entry in S if entry[0] == "M"]


def outputs():
    hs = [
        """{-# LANGUAGE GADTs #-}
{-# LANGUAGE RankNTypes #-}
{-# LANGUAGE ScopedTypeVariables #-}
{-# LANGUAGE ForeignFunctionInterface #-}
-- SPDX-License-Identifier: MPL-2.0
-- Generated by tools/generate_matrix_value_bindings.py.
module HMath.FFI.MatrixValue where
import Control.Exception (evaluate,throwIO)
import Data.Typeable (Typeable,cast)
import Foreign
import Foreign.C
import qualified HMath.Matrix as M
import qualified HMath.FFI.Matrix as Legacy
import qualified HMath.FFI.Value as V
import HMath.FFI.Coefficient
import qualified HMath.FFI.Boundary as B
import HMath.FFI.MathError

withMatrix :: V.Value -> (forall a. Coefficient a => ScalarType a -> M.Matrix a -> IO V.Value) -> IO V.Value
withMatrix (V.Dense (V.SomeMatrix witness matrix)) action = action witness matrix
withMatrix _ _ = V.invalid "expected Matrix value"
withWitness :: V.Value -> (forall a. Coefficient a => ScalarType a -> IO V.Value) -> IO V.Value
withWitness (V.Scalar witness _) action = action witness
withWitness _ _ = V.invalid "expected scalar coefficient prototype"
asMatrix :: forall a. Coefficient a => V.Value -> IO (M.Matrix a)
asMatrix (V.Dense (V.SomeMatrix _ matrix)) = maybe (V.invalid "Matrix coefficient types differ") pure (cast matrix)
asMatrix _ = V.invalid "expected Matrix value"
scalars :: Coefficient a => V.Value -> IO [a]
scalars value = V.asList value >>= mapM V.asScalar
source :: Either HMath.Error.MathError a -> IO a
source = either (throwIO . CallbackMathError) pure
matrixBoundary :: IO CInt -> IO CInt
matrixBoundary action = B.boundary $ callbackBoundary (\\e -> B.checked (Left e) (const (pure ()))) action
apply :: Int -> [V.Value] -> IO V.Value
apply op args = case (op,args) of
""".replace(
            "import HMath.FFI.Coefficient",
            "import qualified HMath.Error\nimport HMath.FFI.Coefficient",
        )
    ]
    c = [
        '/* SPDX-License-Identifier: MPL-2.0 */\n/* Generated by tools/generate_matrix_value_bindings.py. */\n#include "hmath_matrix_value.h"\n#include "matrix_internal.h"\n#include "value_internal.h"\n#include <stdlib.h>\nextern int hm_matrix_value_apply(int opcode,void *const *args,size_t count,void **out);\nextern int hm_dense_export_value(void *matrix,void **out);\nextern int hm_dense_import_value(void *value,void **out);\n'
    ]
    h = [
        """/* SPDX-License-Identifier: MPL-2.0 */
/* Generated by tools/generate_matrix_value_bindings.py. */
#ifndef HMATH_MATRIX_VALUE_H
#define HMATH_MATRIX_VALUE_H
#include "hmath_matrix.h"
#include "hmath_value.h"
/* Structural element types have no invented Num instance. */
#define HMATH_MATRIX_BOOL 16
#define HMATH_MATRIX_STRING 17
#ifdef __cplusplus
extern "C" {
#endif
/* Lossless Matrix core over every supported Num coefficient. Inputs borrow
 * immutable Value owners. Successful outputs own independent references;
 * release with hmath_value_release. Maybe becomes a successful None Value;
 * Either preserves complete MathError and failure leaves out untouched.
 * prototype is a typed coefficient scalar, required by constructors even when
 * the source list is empty. No dtype coercion or mathematical limits added.
 * LU/QR retain their original RealFloat restriction to Float and Double. */
HMATH_API hmath_status hmath_dense_to_value(hmath_context *context,const hmath_dense_matrix *matrix,hmath_value **out);
/* Import real Float/Double Value Matrix into the pre-existing typed Matrix
 * owner. Exact/complex values instead use the generic operations below. */
HMATH_API hmath_status hmath_dense_from_value(hmath_context *context,const hmath_value *value,hmath_dense_matrix **out);
"""
    ]
    mapping = []
    for op, (_, name, kinds, result, mode, expr) in enumerate(OPS):
        args = ["a" + str(i) for i in range(len(kinds))]
        constructor = "m" not in kinds
        full = (["prototype"] if constructor else []) + args
        pattern = ",".join(full)
        prefix = (
            "withWitness prototype $ \\w -> do"
            if constructor
            else "withMatrix " + args[kinds.index("m")] + " $ \\w m -> do"
        )
        hs.append("    (" + str(op) + ",[" + pattern + "]) -> " + prefix + "\n")
        for i, kind in enumerate(kinds):
            arg = args[i]
            if kind == "m" and i == kinds.index("m"):
                hs.append("        let " + arg + "Value = m\n")
            else:
                hs.append(
                    "        "
                    + arg
                    + "Value <- "
                    + {
                        "m": "asMatrix",
                        "i": "V.asIndex",
                        "f": "V.asScalar",
                        "v": "scalars",
                    }[kind]
                    + " "
                    + arg
                    + "\n"
                )
        expression = expr or "M." + name + " " + " ".join(args)
        for arg in reversed(args):
            expression = expression.replace(arg, arg + "Value")
        wrap = "V.Dense . V.SomeMatrix w" if result == "m" else "V.Scalar w"
        if mode == "maybe":
            statement = "pure (maybe V.None (" + wrap + ") (" + expression + "))"
        elif mode == "either":
            statement = "(" + wrap + ") <$> source (" + expression + ")"
        else:
            statement = "pure ((" + wrap + ") (" + expression + "))"
        # Constructor witness must fix result type even if no coefficient list is provided.
        hs.append("        " + statement + "\n")
        symbol = "hmath_matrix_value_" + snake(name)
        proto = (
            "hmath_status "
            + symbol
            + "(hmath_context *context,"
            + ",".join("const hmath_value *" + a for a in full)
            + ",hmath_value **out)"
        )
        h.append("HMATH_API " + proto + ";\n")
        c.append(
            proto
            + " {\n if(!out || "
            + " || ".join("!" + a for a in full)
            + ') return hm_error(HMATH_INVALID_ARGUMENT,"NULL Matrix Value argument");\n hmath_value *result; hmath_status status=hm_value_begin(context,&result); if(status) return status;\n void *args[]={'
            + ",".join("hm_value_stable(" + a + ")" for a in full)
            + "};\n return hm_value_finish(result,hm_matrix_value_apply("
            + str(op)
            + ",args,"
            + str(len(full))
            + ",&result->stable),out);\n}\n"
        )
        mapping.append(
            {
                "symbol": "HMath.Matrix." + name,
                "c": [symbol],
                "python": "hmath.matrix." + snake(name),
                "specializations": [
                    "Float",
                    "Double",
                    "Integer",
                    "Rational",
                    "Complex Float",
                    "Complex Double",
                    "bounded standard integral Num instances",
                    "Numeric.Dual/Quaternion Num instances when constructed as typed scalar Values",
                    *(
                        ["Bool/String and other captured structural codecs"]
                        if name
                        in (
                            "fromList",
                            "fromListChecked",
                            "at",
                            "atChecked",
                            "sliceMatrix",
                            "sliceMatrixChecked",
                            "reshape",
                            "reshapeChecked",
                            "transposeMatrix",
                        )
                        else []
                    ),
                ],
            }
        )
    hs.append("""    (100,[matrix]) -> withMatrix matrix $ \\w m -> pure (V.List (map (V.Scalar w) (M.toList m)))
    (101,[matrix]) -> withMatrix matrix $ \\_ m -> let (r,c)=M.shape m in pure (V.Tuple [V.Index r,V.Index c])
    _ -> V.invalid "invalid Matrix Value operation or arity"
foreign export ccall "hm_matrix_value_apply" ffiApply :: CInt -> Ptr (StablePtr V.Value) -> CSize -> Ptr (StablePtr V.Value) -> IO CInt
ffiApply :: CInt -> Ptr (StablePtr V.Value) -> CSize -> Ptr (StablePtr V.Value) -> IO CInt
ffiApply opcode pointers count out = matrixBoundary $ do
    args <- peekArray (fromIntegral count) pointers >>= mapM deRefStablePtr
    value <- if any structuralValue args then structuralApply (fromIntegral opcode) args else apply (fromIntegral opcode) args
    B.checked (Right ()) (const (V.publish value out))
foreign export ccall "hm_dense_export_value" exportValue :: StablePtr Legacy.Object -> Ptr (StablePtr V.Value) -> IO CInt
exportValue :: StablePtr Legacy.Object -> Ptr (StablePtr V.Value) -> IO CInt
exportValue pointer out = matrixBoundary $ do
    object <- deRefStablePtr pointer
    case object of
        Legacy.M32 m -> B.checked (Right ()) (const (V.publish (V.Dense (V.SomeMatrix SFloat m)) out))
        Legacy.M64 m -> B.checked (Right ()) (const (V.publish (V.Dense (V.SomeMatrix SDouble m)) out))
        _ -> V.invalid "expected legacy real Matrix owner"
foreign export ccall "hm_dense_import_value" importValue :: StablePtr V.Value -> Ptr (StablePtr Legacy.Object) -> IO CInt
importValue :: StablePtr V.Value -> Ptr (StablePtr Legacy.Object) -> IO CInt
importValue pointer out = matrixBoundary $ do
    value <- deRefStablePtr pointer
    case value of
        V.Dense (V.SomeMatrix SFloat m) -> B.checked (Right ()) (const (Legacy.publish (Legacy.M32 m) out))
        V.Dense (V.SomeMatrix SDouble m) -> B.checked (Right ()) (const (Legacy.publish (Legacy.M64 m) out))
        _ -> V.invalid "legacy typed Matrix import requires Float or Double Matrix"
""")
    for name, opcode in [("to_list", 100), ("shape", 101)]:
        symbol = "hmath_matrix_value_" + name
        proto = (
            "hmath_status "
            + symbol
            + "(hmath_context *context,const hmath_value *matrix,hmath_value **out)"
        )
        h.append("HMATH_API " + proto + ";\n")
        c.append(
            proto
            + ' {\n if(!matrix || !out) return hm_error(HMATH_INVALID_ARGUMENT,"NULL Matrix Value argument");\n hmath_value *result; hmath_status status=hm_value_begin(context,&result); if(status) return status;\n void *args[]={hm_value_stable(matrix)};\n return hm_value_finish(result,hm_matrix_value_apply('
            + str(opcode)
            + ",args,1,&result->stable),out);\n}\n"
        )
        mapping.append(
            {
                "symbol": "HMath.Matrix."
                + ("toList" if name == "to_list" else "shape"),
                "c": [symbol],
                "python": "hmath.matrix." + name,
                "specializations": [
                    "same standard coefficients and Bool/String structural elements as Matrix Value"
                ],
            }
        )
    c.append("""hmath_status hmath_dense_to_value(hmath_context *context,const hmath_dense_matrix *matrix,hmath_value **out) {
 if(!matrix || matrix->kind!=1 || !out) return hm_error(HMATH_INVALID_ARGUMENT,"expected Matrix owner/output");
 hmath_value *result; hmath_status status=hm_value_begin(context,&result); if(status) return status;
 return hm_value_finish(result,hm_dense_export_value(matrix->stable,&result->stable),out);
}
hmath_status hmath_dense_from_value(hmath_context *context,const hmath_value *value,hmath_dense_matrix **out) {
 if(!value || value->kind!=9 || (value->dtype!=0 && value->dtype!=1) || !out)
  return hm_error(HMATH_INVALID_ARGUMENT,"typed Matrix import requires Float or Double Matrix");
 struct hmath_dense_object *result=calloc(1,sizeof *result);
 if(!result) return hm_error(HMATH_ALLOCATION_FAILED,"dense handle allocation failed");
 hmath_status status=hm_enter(context); if(status) { free(result); return status; }
 status=(hmath_status)hm_dense_import_value(value->stable,&result->stable);
 if(status) { free(result); hm_leave(); return status; }
 atomic_init(&result->refs,1); result->kind=1; result->precision=value->dtype==1 ? 32 : 64; *out=result;
 return HMATH_OK;
}
""")
    h.append("#ifdef __cplusplus\n}\n#endif\n#endif\n")
    return {
        "src/HMath/FFI/MatrixValue.hs": "".join(hs) + structural_haskell(),
        "include/hmath_matrix_value.h": "".join(h),
        "cbits/matrix_value.c": "".join(c),
        "bindings/schema/matrix-value-objects.json": json.dumps(
            {"schema": 1, "extends": "matrix-objects.json", "bindings": mapping},
            indent=2,
        )
        + "\n",
    }


def structural_haskell():
    lines = [
        "\n-- Original structure-only operations over Bool/String or a captured codec.\n",
        "structuralValue :: V.Value -> Bool\nstructuralValue (V.Boolean _) = True\nstructuralValue (V.Text _) = True\nstructuralValue (V.Dense(V.StructuralMatrix _ _ _ _ _)) = True\nstructuralValue _ = False\n",
        'withStructural :: V.Value -> (forall a. Typeable a => Int -> (a -> IO V.Value) -> (V.Value -> IO a) -> (a -> IO ()) -> IO V.Value) -> IO V.Value\nwithStructural (V.Boolean _) action = action 16 (pure . V.Boolean) V.asBoolean (\\x -> evaluate x >> pure ())\nwithStructural (V.Text _) action = action 17 (pure . V.Text) V.asText (mapM_ evaluate)\nwithStructural (V.Dense(V.StructuralMatrix dtype writer reader force _)) action = action dtype writer reader force\nwithStructural _ _ = V.invalid "expected structural element prototype/Matrix"\n',
        "structuralApply :: Int -> [V.Value] -> IO V.Value\nstructuralApply op args = case(op,args) of\n",
    ]
    for opcode, (_mod, name, kinds, result, mode, expression) in enumerate(OPS):
        if name not in (
            "fromList",
            "fromListChecked",
            "at",
            "atChecked",
            "sliceMatrix",
            "sliceMatrixChecked",
            "reshape",
            "reshapeChecked",
            "transposeMatrix",
        ):
            continue
        variables = ["a" + str(i) for i in range(len(kinds))]
        constructor = "m" not in kinds
        full = (["prototype"] if constructor else []) + variables
        owner = "prototype" if constructor else variables[kinds.index("m")]
        lines.append(
            "    ("
            + str(opcode)
            + ",["
            + ",".join(full)
            + "]) -> withStructural "
            + owner
            + (
                " $ \\dtype writer reader force -> do\n"
                if result == "m"
                else " $ \\_dtype writer _reader _force -> do\n"
            )
        )
        for i, kind in enumerate(kinds):
            variable = variables[i]
            decoder = {
                "m": "V.asMatrix",
                "i": "V.asIndex",
                "v": "(\\x -> V.asList x >>= mapM reader)",
            }[kind]
            lines.append(
                "        " + variable + "Value <- " + decoder + " " + variable + "\n"
            )
        call = expression or "M." + name + " " + " ".join(variables)
        for variable in reversed(variables):
            call = call.replace(variable, variable + "Value")
        wrap = (
            "(V.Dense . V.StructuralMatrix dtype writer reader force)"
            if result == "m"
            else "writer"
        )
        if mode == "maybe":
            if result == "m":
                statement = "pure(maybe V.None " + wrap + " (" + call + "))"
            else:
                statement = "maybe (pure V.None) writer (" + call + ")"
        elif mode == "either":
            statement = (
                "source ("
                + call
                + ") >>= "
                + ("pure . " + wrap if result == "m" else "writer")
            )
        else:
            statement = "pure(" + wrap + " (" + call + "))"
        lines.append("        " + statement + "\n")
    lines.extend(
        [
            "    (100,[matrix]) -> withStructural matrix $ \\_ writer _ _ -> do\n        values <- V.asMatrix matrix\n        V.List <$> mapM writer (M.toList values)\n",
            "    (101,[matrix]) -> withStructural matrix $ \\_ _ (_reader :: V.Value -> IO a) _ -> do\n        values <- (V.asMatrix matrix :: IO(M.Matrix a))\n        let (rows,columns)=M.shape values\n        pure(V.Tuple[V.Index rows,V.Index columns])\n",
            '    _ -> V.unsupported "original structural element type has no Num instance"\n',
        ]
    )
    return "".join(lines)


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    for name, data in outputs().items():
        path = ROOT / name
        if args.check:
            if not path.exists() or path.read_text() != data:
                raise SystemExit("Stale: " + name)
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(data)
